const rules=[['Boundaries','Join complete clauses with a period, semicolon, or comma + FANBOYS.','The trial ended; the team reviewed the data.'],['Commas','Use commas after introductory dependent clauses and around nonessential information. Never split a subject from its verb.','Although it rained, we continued.'],['Colons and dashes','A colon must follow a complete clause. Match dashes around an insertion.','We needed two supplies: paper and ink.'],['Agreement','Match the verb to the actual subject, ignoring intervening phrases.','The collection of maps is valuable.'],['Verbs','Follow the timeline. Use had + participle for an action completed before another past event.','By the time we arrived, the lake had frozen.'],['Pronouns and possession','Its is possessive; it’s means it is or it has. Plural possessives usually end in s’.','The students’ projects won awards.'],['Modifiers','Place a describing phrase next to the person or thing it describes.','Walking home, Maya saw a fox.'],['Parallel structure','Use matching grammatical forms in lists. Compare equivalent things.','She enjoys reading, hiking, and painting.']];
const bank=[
[0,'The sample was small ___ the team repeated the experiment.',[';',',','and','no punctuation'],0,'Both sides are complete clauses. A semicolon joins them.'],
[0,'The results were promising ___ however, further trials were needed.',[';',',','no punctuation',': however'],0,'However is not a coordinating conjunction. A boundary belongs before it.'],
[0,'The storm intensified ___ so the hikers returned.',['no punctuation',',',';',': so'],1,'A comma plus so joins independent clauses.'],
[0,'Because the instrument needed calibration, ___.',['a delicate instrument','before the trial','the technician adjusted it','needing adjustment'],2,'The dependent opening needs an independent main clause.'],
[1,'Although the first attempt failed ___ the team continued.',[';',':',',','no punctuation'],2,'Use a comma after an introductory dependent clause.'],
[1,'The discovery of several ancient coins ___ surprised historians.',[',',';',':','no punctuation'],3,'Keep the subject discovery beside its verb surprised.'],
[1,'The sensor, which was installed yesterday ___ detected a leak.',[';',',',':','no punctuation'],1,'The nonessential insertion needs a closing comma.'],
[2,'The team needed three supplies ___ gloves, jars, and labels.',[';',',',':','no punctuation'],2,'A complete clause introduces the list with a colon.'],
[2,'The team packed ___ gloves, jars, and labels.',['no punctuation',':',';',','],0,'Do not put a colon between a verb and its objects.'],
[2,'The instrument—a student-built prototype ___ passed the test.',['—',',',';','no punctuation'],0,'Match the opening dash with a closing dash.'],
[3,'The collection of rare books ___ valuable.',['are','is','were','have been'],1,'Collection is singular. Of rare books does not change that.'],
[3,'Each of the participants ___ a notebook.',['have','has','are carrying','were given'],1,'Each takes a singular verb.'],
[3,'Beneath the floorboards ___ several documents.',['is','was','are','has been'],2,'The plural subject documents follows the verb.'],
[3,'The teacher, along with her students, ___ attending.',['are','were','have been','is'],3,'Along with does not make teacher plural.'],
[4,'By the time the lecture began, the students ___ the article.',['have read','will read','had read','are reading'],2,'Had read marks completion before began.'],
[4,'Yesterday, the team collected samples and ___ observations.',['records','recorded','will record','has recorded'],1,'Recorded matches the past timeline.'],
[4,'The scientist has ___ three reports.',['wrote','writing','write','written'],3,'Has requires the past participle written.'],
[5,'The company revised ___ policy.',['it’s','its','they’re','there'],1,'Its expresses possession.'],
[5,'The researchers placed ___ notes in separate folders.',['their','they’re','there','its'],0,'Their refers to the researchers and expresses possession.'],
[5,'Several students left bags outside. The teacher brought the ___ bags inside.',['student’s','students’','students','students’s'],1,'Multiple students own the bags: students’.'],
[5,'The instructor spoke to Jordan and ___.',['I','myself','me','mine'],2,'The preposition to takes the object pronoun me.'],
[6,'Walking through the museum, ___.',['the paintings impressed Maya','Maya admired the paintings','there were many paintings','the paintings looked beautiful'],1,'Maya is walking, so Maya must follow the modifier.'],
[6,'Designed to withstand strong winds, ___.',['engineers praised the bridge','the storm tested the bridge','the bridge remained stable','there was little damage'],2,'The bridge is what was designed.'],
[6,'After examining the manuscript, ___.',['its symbols puzzled the historian','there were strange symbols','several symbols were visible','the historian identified several symbols'],3,'The historian examined it and must follow the opening phrase.'],
[7,'The course teaches students to observe, to analyze, and ___.',['writing clearly','to write clearly','clear writing','they write clearly'],1,'To write matches to observe and to analyze.'],
[7,'She enjoys hiking, swimming, and ___.',['to cycle','she cycles','cycling','a bicycle'],2,'Cycling matches the other -ing forms.'],
[7,'The eagle’s wingspan is greater than ___.',['the hawk','that of the hawk','the hawk is','those of the hawk'],1,'Compare a wingspan with another wingspan. That replaces wingspan.']
].map((q,id)=>({id,t:q[0],text:q[1],choices:q[2],a:q[3],why:q[4]}));
let s;try{s=JSON.parse(localStorage.getItem('grammarLab'))}catch{}if(!s||!Array.isArray(s.missed))s={tries:0,right:0,streak:0,missed:[]};let mode='practice',topic='all',queue=[],index=0,choice=null,checked=false,score=0;const app=document.getElementById('app');
const escapeText=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('grammarLab',JSON.stringify(s))}catch{}stats()}
function stats(){document.getElementById('accuracy').textContent=s.tries?Math.round(s.right/s.tries*100)+'%':'—';document.getElementById('reps').textContent=s.tries;document.getElementById('streak').textContent=s.streak;document.getElementById('missCount').textContent=s.missed.length?'('+s.missed.length+')':''}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function start(){queue=shuffle(bank.filter(q=>mode==='review'?s.missed.includes(q.id):topic==='all'||q.t===Number(topic)));if(mode==='challenge')queue=queue.slice(0,10);index=0;score=0;choice=null;checked=false;render()}
function render(){document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(mode==='rules'){app.innerHTML='<div class="rules">'+rules.map((r,i)=>'<article class="panel"><span class="tag">RULE '+(i+1)+'</span><h3>'+r[0]+'</h3><p>'+r[1]+'</p><div class="rule-example">'+r[2]+'</div><button data-topic="'+i+'" style="margin-top:16px">Practice this rule →</button></article>').join('')+'</div>';app.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{mode='practice';topic=b.dataset.topic;start()});return}
if(!queue.length||index>=queue.length){app.innerHTML='<section class="panel empty"><h2>'+(!queue.length?'No mistakes waiting.':'Session complete: '+score+' / '+queue.length)+'</h2><p>'+(!queue.length?'Missed questions will appear here. Correct answers in review clear them.':'Your missed questions are ready in Mistake review.')+'</p><button class="primary" id="again">Practice again →</button> <button id="review">Review mistakes</button></section>';document.getElementById('again').onclick=()=>{mode='practice';start()};document.getElementById('review').onclick=()=>{mode='review';start()};return}
const q=queue[index];app.innerHTML='<div class="layout"><section class="panel"><div class="toolbar"><span class="tag">'+mode.toUpperCase()+'</span><small>'+(index+1)+' / '+queue.length+'</small></div><div class="progress"><div style="width:'+index/queue.length*100+'%"></div></div>'+(mode==='practice'?'<label for="topic">Focus: </label><select id="topic"><option value="all">All topics</option>'+rules.map((r,i)=>'<option value="'+i+'" '+(String(topic)===String(i)?'selected':'')+'>'+r[0]+'</option>').join('')+'</select>':'')+'<p class="muted">Choose the answer that follows Standard English conventions.</p><div class="question">'+escapeText(q.text)+'</div><div class="choices">'+q.choices.map((c,i)=>'<button class="choice '+(choice===i?'selected ':'')+(checked&&i===q.a?'correct ':'')+(checked&&choice===i&&i!==q.a?'wrong':'')+'" data-choice="'+i+'" '+(checked?'disabled':'')+'><span class="letter">'+String.fromCharCode(65+i)+'</span>'+escapeText(c)+'</button>').join('')+'</div>'+(checked?'<div class="feedback" role="status"><b>'+(choice===q.a?'Correct!':'Answer: '+String.fromCharCode(65+q.a)+'.')+'</b> '+q.why+'<br><small>Rule: '+rules[q.t][0]+'</small></div>':'')+'<div class="actions"><button class="primary" id="action" '+(!checked&&choice===null?'disabled':'')+'>'+(checked?(index===queue.length-1?'See results':'Next question →'):'Check answer')+'</button></div></section><aside class="panel sidebar"><div class="eyebrow">YOUR GAME PLAN</div><h3>Find the rule first.</h3><p>1. Compare the choices.<br>2. Find the subject and main verb.<br>3. Check for complete clauses.<br>4. Apply the rule and reread.</p><p><b>Study tip</b><br>A pause in your voice doesn’t automatically call for a comma.</p><small>27 original questions · 8 topics</small></aside></div>';
const filter=document.getElementById('topic');if(filter)filter.onchange=e=>{topic=e.target.value;start()};app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choice=Number(b.dataset.choice);render()});document.getElementById('action').onclick=()=>{if(checked){index++;choice=null;checked=false;render();return}if(choice===null)return;checked=true;s.tries++;if(choice===q.a){score++;s.right++;s.streak++;if(mode==='review')s.missed=s.missed.filter(id=>id!==q.id)}else{s.streak=0;if(!s.missed.includes(q.id))s.missed.push(q.id)}save();render()}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;topic='all';start()});document.getElementById('reset').onclick=()=>{if(confirm('Reset your saved progress?')){s={tries:0,right:0,streak:0,missed:[]};save();start()}};stats();start();